    "description": "This digital elevation model (DEM/DTM) was produced as part of an effort to characterize topography within candidate Human Exploration Zones for Mars. The DEM was constructed from a pair of CTX images using the stereo photogrammetry software AMES Stereo Pipeline (ASP). THe DEM has been tied to MOLA and can be considered resarch- and visualization-ready. Because it has not been manually edited using a full 3D editing environment, ASP DEMs cannot currently be considered true engineering-ready for performing landings. References: Shean, D. E., O. Alexandrov, Z. Moratto, B. E. Smith, I. R. Joughin, C. C. Porter, P. J., Morin, 2016, An automated, open-source pipeline for mass production of digital elevation models (DEMs) from very high-resolution commercial stereo satellite imagery, ISPRS Journal of Photogrammetry and Remote Sensing, 116. Mayer, D. P., E. S. Kite, 2016, An Integrated Workflow for Producing Digital Terrain Models Of Mars from CTX And HiRISE Stereo Data Using the NASA Ames Stereo Pipeline, 47th Lunar and Planetary Science Conference, Abstract 1261."
